fixedSource: |
  MemoryStream output = new MemoryStream();
  SaveReport(output);
  Console.WriteLine(output.Length);

  static void SaveReport(Stream target)
  {
      using ReportFile report = new ReportFile(target);
      report.Write("Total: 3");
      report.Dispose();
  }

  class ReportFile : IDisposable
  {
      private readonly StreamWriter _writer;
      private bool _disposed;

      public ReportFile(Stream target)
      {
          _writer = new StreamWriter(target, leaveOpen: true);
      }

      public void Write(string text) => _writer.Write(text);

      public void Dispose()
      {
          if (_disposed)
          {
              return;
          }
          _writer.Flush();
          _writer.Dispose();
          _disposed = true;
      }
  }
